static int16_t pcm(float v) { if(v>32767) return 32767; if(v< -32768) return -32768; return (int16_t)lrintf(v); }
void aec_resample_reset(aec_decimator_t *d, aec_interpolator_t *u) { memset(d,0,sizeof(*d)); memset(u,0,sizeof(*u)); }
bool aec_decimate(aec_decimator_t *d, int16_t ref, int16_t mic, int16_t *r, int16_t *m) {
    d->history[0][d->pos]=d->history[0][d->pos+AEC_FIR_TAPS]=ref;
    d->history[1][d->pos]=d->history[1][d->pos+AEC_FIR_TAPS]=mic;
    unsigned newest=d->pos; d->pos=(d->pos+1)%AEC_FIR_TAPS;
    if(++d->phase<3) return false;
    d->phase=0;
    float a=0,b=0; for(unsigned k=0;k<AEC_FIR_TAPS;k++) { unsigned p=newest+AEC_FIR_TAPS-k; a+=taps[k]*d->history[0][p]; b+=taps[k]*d->history[1][p]; }
    *r=pcm(a); *m=pcm(b); return true;
}
void aec_interpolate(aec_interpolator_t *u, int16_t input, int16_t output[3]) {
    // Polyphase form: avoid multiplying the two inserted zero samples.
    enum { HISTORY=(AEC_FIR_TAPS+2)/3 };
    u->history[u->pos]=u->history[u->pos+HISTORY]=input;
    for(unsigned phase=0;phase<3;phase++) {
        float v=0;
        for(unsigned k=0;phase+3*k<AEC_FIR_TAPS;k++) v+=3*taps[phase+3*k]*u->history[u->pos+HISTORY-k];
        output[phase]=pcm(v);
    }
    u->pos=(u->pos+1)%HISTORY;
}
